      "ಡೇಟಾ ಉಳಿತಾಯ: ಅಗತ್ಯವಿದ್ದಾಗ ಮಾತ್ರ ವೀಡಿಯೊ ಲೋಡ್ ಮಾಡುತ್ತದೆ, ಅನಿಮೇಷನ್ ನಿಲ್ಲಿಸುತ್ತದೆ. ಕಡಿಮೆ ಇಂಟರ್ನೆಟ್ ವೇಗದ ಶಾಲೆಗಳಿಗಾಗಿ.",
      "ഡാറ്റ ലാഭിക്കൽ: ആവശ്യമുള്ളപ്പോൾ മാത്രം വീഡിയോകൾ ലോഡ് ചെയ്യുന്നു; അനിമേഷനുകൾ നിർത്തുന്നു. കുറഞ്ഞ ഇന്റർനെറ്റ് വേഗമുള്ള സ്കൂളുകൾക്കായി.",
