    ", பின்னர் அதன் கோப்புப் பகிர்வு இணைப்பை இங்கே ஒட்டவும். கோப்புறை அல்லது Google Doc அல்ல, PDF கோப்பைப் பயன்படுத்தவும். இணைப்பு மட்டுமே சேமிக்கப்படும்; ஆவணம் உங்கள் Drive-ல் இருக்கும் மற்றும் இங்கே முன்னோட்டம் காட்டப்படும். உரை-மட்டும் குறிப்புகளுக்கு இது விருப்பமானது.",
    ", ನಂತರ ಅದರ ಫೈಲ್-ಹಂಚಿಕೆ ಲಿಂಕ್ ಅನ್ನು ಇಲ್ಲಿ ಅಂಟಿಸಿ. ಫೋಲ್ಡರ್ ಅಥವಾ Google Doc ಬದಲು PDF ಫೈಲ್ ಬಳಸಿ. ಲಿಂಕ್ ಮಾತ್ರ ಉಳಿಸಲಾಗುತ್ತದೆ; ದಾಖಲೆ ನಿಮ್ಮ Drive ನಲ್ಲೇ ಇರುತ್ತದೆ ಮತ್ತು ಇಲ್ಲಿ ಪೂರ್ವವೀಕ್ಷಣೆ ಆಗುತ್ತದೆ. ಪಠ್ಯ-ಮಾತ್ರ ಟಿಪ್ಪಣಿಗಳಿಗೆ ಇದು ಐಚ್ಛಿಕ.",
