    "உங்கள் வகுப்புக்கான மதிப்பீடுகளை ஆசிரியர்கள் பதிவேற்றுகிறார்கள். விரைவில் மீண்டும் பாருங்கள்!",
    "ನಿಮ್ಮ ತರಗತಿಗೆ ಮೌಲ್ಯಮಾಪನಗಳನ್ನು ಶಿಕ್ಷಕರು ಅಪ್‌ಲೋಡ್ ಮಾಡುತ್ತಿದ್ದಾರೆ. ಶೀಘ್ರದಲ್ಲಿ ಮತ್ತೆ ನೋಡಿ!",
