  "Pragyan is running, but the learning database is not available yet. No accounts, notes, or scores have been saved to temporary storage.": [
    "ప్రజ్ఞాన్ నడుస్తోంది, కానీ అభ్యాస డేటాబేస్ ఇంకా అందుబాటులో లేదు. ఖాతాలు, గమనికలు లేదా స్కోర్లు తాత్కాలిక నిల్వకు భద్రపరచబడలేదు.",
    "प्रज्ञान चल रहा है, लेकिन शिक्षण डेटाबेस अभी उपलब्ध नहीं है। कोई खाता, टिप्पणी या अंक अस्थायी भंडारण में सहेजे नहीं गए हैं।",
    "பிரக்ஞான் இயங்குகிறது, ஆனால் கற்றல் தரவுத்தளம் இன்னும் கிடைக்கவில்லை. கணக்குகள், குறிப்புகள் அல்லது மதிப்பெண்கள் தற்காலிக சேமிப்பில் சேமிக்கப்படவில்லை.",
    "ಪ್ರಜ್ಞಾನ್ ಚಾಲನೆಯಲ್ಲಿದೆ, ಆದರೆ ಕಲಿಕಾ ಡೇಟಾಬೇಸ್ ಇನ್ನೂ ಲಭ್ಯವಿಲ್ಲ. ಯಾವುದೇ ಖಾತೆ, ಟಿಪ್ಪಣಿ ಅಥವಾ ಅಂಕಗಳು ತಾತ್ಕಾಲಿಕ ಸಂಗ್ರಹಣೆಗೆ ಉಳಿಸಲಾಗಿಲ್ಲ.",
    "പ്രജ്ഞാൻ പ്രവർത്തിക്കുന്നു, പക്ഷേ പഠന ഡാറ്റാബേസ് ഇതുവരെ ലഭ്യമല്ല. അക്കൗണ്ടുകളോ കുറിപ്പുകളോ സ്കോറുകളോ താൽക്കാലിക സംഭരണത്തിൽ സേവ് ചെയ്തിട്ടില്ല.",
  ],
  "Pragyan uses NCERT Learning Outcome mapping (e.g. LO-8-SCI-06) and DIKSHA QR codes. Local SQLite or permanent hosted SQLite stores your session data, depending on the deployment.": [
    "ప్రజ్ఞాన్ NCERT అభ్యాస ఫలిత మ్యాపింగ్ (ఉదా. LO-8-SCI-06) మరియు DIKSHA QR కోడ్‌లను ఉపయోగిస్తుంది. డిప్లాయిమెంట్‌ను బట్టి స్థానిక SQLite లేదా శాశ్వత హోస్టెడ్ SQLite మీ సెషన్ డేటాను నిల్వ చేస్తుంది.",
    "प्रज्ञान NCERT अधिगम परिणाम मैपिंग (जैसे LO-8-SCI-06) और DIKSHA QR कोड का उपयोग करता है। डिप्लॉयमेंट के अनुसार स्थानीय SQLite या स्थायी होस्टेड SQLite आपका सत्र डेटा संग्रहीत करता है।",
    "பிரக்ஞான் NCERT கற்றல் விளைவு வரைபடம் (எ.கா. LO-8-SCI-06) மற்றும் DIKSHA QR குறியீடுகளைப் பயன்படுத்துகிறது. செயல்படுத்தலைப் பொறுத்து உள்ளூர் SQLite அல்லது நிரந்தர ஹோஸ்ட் செய்யப்பட்ட SQLite உங்கள் அமர்வுத் தரவைச் சேமிக்கிறது.",
    "ಪ್ರಜ್ಞಾನ್ NCERT ಕಲಿಕಾ ಫಲಿತಾಂಶ ಮ್ಯಾಪಿಂಗ್ (ಉದಾ. LO-8-SCI-06) ಮತ್ತು DIKSHA QR ಕೋಡ್‌ಗಳನ್ನು ಬಳಸುತ್ತದೆ. ನಿಯೋಜನೆಯನ್ನು ಅವಲಂಬಿಸಿ ಸ್ಥಳೀಯ SQLite ಅಥವಾ ಶಾಶ್ವತ ಹೋಸ್ಟೆಡ್ SQLite ನಿಮ್ಮ ಸೆಶನ್ ಡೇಟಾವನ್ನು ಸಂಗ್ರಹಿಸುತ್ತದೆ.",
    "പ്രജ്ഞാൻ NCERT പഠന ഫല മാപ്പിംഗ് (ഉദാ. LO-8-SCI-06), DIKSHA QR കോഡുകൾ എന്നിവ ഉപയോഗിക്കുന്നു. ഡിപ്ലോയ്മെന്റിനെ ആശ്രയിച്ച് ലോക്കൽ SQLite അല്ലെങ്കിൽ ശാശ്വത ഹോസ്റ്റഡ് SQLite നിങ്ങളുടെ സെഷൻ ഡാറ്റ സംഭരിക്കും.",
  ],
