    "ಟೋಲ್-ಫ್ರೀ 1800-11-8004 (ಸೋಮ–ಶನಿ, ಬೆಳಿಗ್ಗೆ 8 – ರಾತ್ರಿ 8 IST)",
    "ടോൾ-ഫ്രീ 1800-11-8004 (തിങ്കൾ–ശനി, രാവിലെ 8 – രാത്രി 8 IST)",
